#!/usr/bin/env bash
# GLM 5.3 as a third executor, paper writer route for the added writers: 18 executor-only replays of the frozen four-condition memories (Inkling, Flash; three seeds per domain) via writer_variants_run --source-run. Executor-only replays: the frozen memories of each finished run are reused and only
# the executor stage runs with glm_5_3_baseten, so the writer-side results are byte-identical to the source run. Sequential.
set -u
export PATH="$HOME/.local/bin:/c/Users/mikad/.local/bin:$PATH"
cd "$(dirname "$0")"
LOG="${1:-results/driver_$(basename "$0" .sh).log}"
run() {
  local tag; tag=$(printf '%s
' "$@" | awk '/^--tag$/{getline; print; exit}')
  if [ -n "$tag" ] && ls -d results/*/*__"$tag" >/dev/null 2>&1 && grep -lq '"status": "completed"' results/*/*__"$tag"/manifest.json 2>/dev/null; then echo "=== $(date +%H:%M) SKIP (completed run exists) $tag" >> "$LOG"; return 0; fi
  echo "=== $(date +%H:%M) $*" >> "$LOG"; uv run python -m "$@" >> "$LOG" 2>&1 || echo "FAILED: $*" >> "$LOG"
}
echo "=== $(date +%H:%M) PHASE 28a START" >> "$LOG"
